def seed_batches(apps, schema_editor):
    """Today's stock split into batches: on-hand attributed to the newest incoming movements (FIFO estimate), the rest 'no batch'."""
    Stock = apps.get_model("stores", "StoreProductStock")
    Move = apps.get_model("stores", "StockMovement")
    Batch = apps.get_model("stores", "StockBatch")
    for row in Stock.objects.filter(quantity__gt=0):
        need, parts = row.quantity, {}
        for m in Move.objects.filter(store_id=row.store_id, product_variant_id=row.product_variant_id, quantity__gt=0,
                                     movement_type__in=["receipt", "transfer_in", "return", "adjustment"]).order_by("-created_at"):
            if need <= 0:
                break
            take = min(need, m.quantity)
            key = (m.batch_number or "", m.expiry_date)
            parts[key] = parts.get(key, 0) + take
            need -= take
        if need > 0:
            parts[("", None)] = parts.get(("", None), 0) + need
        for (batch, expiry), qty in parts.items():
            Batch.objects.create(store_id=row.store_id, product_variant_id=row.product_variant_id, batch_number=batch, expiry_date=expiry, quantity=qty)


